import sys
from collections import defaultdict

def compute_distribution(m, sides):
    """
    Computes the probability distribution of the sum of m dice with sides sides.
    """
    dp = defaultdict(int)
    dp[0] = 1  # Base case: sum 0 occurs in 1 way (no dice rolled)

    for _ in range(m):
        new_dp = defaultdict(int)
        for prev_sum, count in dp.items():
            for face in range(1, sides + 1):
                new_dp[prev_sum + face] += count
        dp = new_dp

    total = sides ** m
    return {k: v / total for k, v in dp.items()}

def main():
    m, a, n, b = map(int, sys.stdin.read().split())

    # Compute the probability distribution for both dice rolls
    alice_dist = compute_distribution(m, a)
    bob_dist = compute_distribution(n, b)

    # Calculate the probability that the sums are equal
    result = 0.0
    for s in alice_dist:
        if s in bob_dist:
            result += alice_dist[s] * bob_dist[s]

    # Output the result with 6 decimal places
    print(f"{result:.6f}")

if __name__ == "__main__":
    main()

use std::collections::HashMap;
use std::io;

fn compute_distribution(m: usize, sides: usize) -> HashMap<usize, f64> {
    let mut dp = HashMap::new();
    dp.insert(0, 1);

    for _ in 0..m {
        let mut new_dp = HashMap::new();
        for (&prev_sum, &count) in &dp {
            for face in 1..=sides {
                let new_sum = prev_sum + face;
                new_dp.entry(new_sum).and_modify(|v| *v += count).or_insert(count);
            }
        }
        dp = new_dp;
    }

    let total = sides.pow(m as u32) as f64;
    let mut result = HashMap::new();
    for (k, &v) in &dp {
        result.insert(*k, v as f64 / total);
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let m: usize = iter.next().unwrap().parse().unwrap();
    let a: usize = iter.next().unwrap().parse().unwrap();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let b: usize = iter.next().unwrap().parse().unwrap();

    let alice_dist = compute_distribution(m, a);
    let bob_dist = compute_distribution(n, b);

    let mut result = 0.0;
    for (&sum, &prob_a) in &alice_dist {
        if let Some(&prob_b) = bob_dist.get(&sum) {
            result += prob_a * prob_b;
        }
    }

    println!("{:.6}", result);
}

